  { key: 'ai_overview', label: 'AI Overview', color: '#FBBC04' }
];

// Share of Voice, como lo define la Estrategia SEO/GEO de BCP: «visibilidad de
// la marca vs la competencia, con un score que pondera el peso de la posición,
// la prominencia y el contexto (positivo/neutral)». Sin dependencias: build.mjs
// lo pega en «Armar fila» y en «Datos del monitor».
//
// Score de cada banco en una respuesta:
//   posición     1 / posición               (1.º = 1, 2.º = 0,5, 3.º = 0,33…)
//   prominencia  sus menciones ÷ menciones de todos los bancos
//   contexto     positivo 1 · neutral 0,75 · negativo 0,25
//   score = (posición + prominencia) / 2 × contexto
// SoV de un banco = su score ÷ la suma de los scores de todos los bancos × 100.

function pesoContexto(sentimiento) {
  const s = Number(sentimiento);
  if (!isFinite(s)) return 0.75;
  return s > 0.2 ? 1 : s < -0.2 ? 0.25 : 0.75;
}

// detalle: [{marca, posicion, menciones, sentimiento}] → {marca: SoV 0-100}
function sovPorMarca(detalle) {
  const lista = (detalle || []).filter(d => d && d.marca);
  const totalMenciones = lista.reduce((n, d) => n + Math.max(0, Number(d.menciones) || 0), 0);
  const scores = {};
  for (const d of lista) {
    const pos = Number(d.posicion) > 0 ? 1 / Number(d.posicion) : 0;
    const prom = totalMenciones > 0 ? Math.max(0, Number(d.menciones) || 0) / totalMenciones : 0;
    scores[d.marca] = (scores[d.marca] || 0) + ((pos + prom) / 2) * pesoContexto(d.sentimiento);
  }
  const total = Object.values(scores).reduce((n, v) => n + v, 0);
  const sov = {};
  for (const m of Object.keys(scores)) sov[m] = total > 0 ? Math.round((scores[m] / total) * 1000) / 10 : 0;
  return sov;
}

// Detalle aproximado para filas sin desglose por banco: el orden de
// marcas_mencionadas da la posición, una mención cada uno y contexto neutral
// salvo BCP, que usa su sentimiento.
function detalleDesdeRanking(marcas, marcaPropia, sentimientoPropio, mencionesPropias) {
  return (marcas || []).map((m, i) => ({
    marca: m,
    posicion: i + 1,
    menciones: m === marcaPropia && mencionesPropias > 0 ? mencionesPropias : 1,
    // Sin desglose no hay sentimiento de los competidores: null (desconocido), no 0.
    sentimiento: m === marcaPropia ? sentimientoPropio : null
  }));
}

// El Analista devuelve el detalle como texto JSON. Se acepta con o sin
// ```json, y si no se puede leer se devuelve [].
function leerDetalle(texto) {
  if (Array.isArray(texto)) return texto;
  const s = String(texto || '').replace(/```(json)?/gi, '').trim();
  if (!s) return [];
  try {
    const v = JSON.parse(s.slice(s.indexOf('['), s.lastIndexOf(']') + 1));
    return Array.isArray(v) ? v : [];
  } catch (e) {
    return [];
  }
}

// Lo que hace la corrida con las respuestas de los motores. Sin dependencias:
// build.mjs pega este archivo en los nodos Code «Juntar respuestas» y «Armar
// fila», y test.mjs lo carga igual para probarlo.
//
// Mencion, posicion, sentimiento y marcas los decide el nodo «Analista IA»
// (Information Extractor). Aqui solo se saca el texto y las fuentes de cada
// API, y se calcula citado_bcp, que sale de los dominios y no necesita IA.

// Sin `new URL`: el sandbox de los nodos Code de n8n no siempre lo trae.
function dominioDe(url) {
  const m = String(url || '').trim().toLowerCase().match(/^(?:[a-z][a-z0-9+.-]*:\/\/)?(?:[^@\/?#]*@)?([^\/?#:]+)/);
  const host = m ? m[1].replace(/^www\./, '').replace(/\.$/, '') : '';
  return /^[a-z0-9-]+(\.[a-z0-9-]+)+$/.test(host) ? host : '';
}

function esDominioPropio(dominio, dominios) {
  return dominios.some(d => dominio === d || dominio.endsWith('.' + d));
}

// Saca el texto, las fuentes ({url, title}) y las consultas de búsqueda que hizo
// el motor (fan-out) de lo que devuelve cada API. Si la llamada falló (el nodo
// HTTP sigue con {error}), lo deja anotado en vez de parar la corrida.
function extraerRespuesta(motor, r) {
  r = r || {};
  const vacia = { disponible: false, texto: '', fuentes: [], consultas: [], error: '' };
  if (r.error) {
    const e = r.error;
    const msg = typeof e === 'string' ? e : (e.message || (e.error && e.error.message) || JSON.stringify(e));
    return Object.assign(vacia, { error: String(msg).slice(0, 500) });
  }
  const f = (url, title) => ({ url: String(url || ''), title: String(title || '') });
  if (motor === 'chatgpt') {
    const msg = (r.choices && r.choices[0] && r.choices[0].message) || {};
    const fuentes = (msg.annotations || [])
      .filter(a => a.type === 'url_citation' && a.url_citation)
      .map(a => f(a.url_citation.url, a.url_citation.title));
    return { disponible: true, texto: msg.content || '', fuentes, consultas: [], error: '' };
  }
  if (motor === 'claude') {
    // Con búsqueda web, el texto llega partido en bloques (uno por cita): se
    // une sin separador para no cortar frases.
    const texto = (r.content || []).filter(c => c.type === 'text').map(c => c.text).join('');
    const fuentes = [];
    for (const c of r.content || []) for (const cit of c.citations || []) if (cit.url) fuentes.push(f(cit.url, cit.title));
    // Si no citó nada pero sí buscó, cuentan las páginas que consultó.
    if (!fuentes.length) {
      for (const c of r.content || []) {
        if (c.type === 'web_search_tool_result' && Array.isArray(c.content)) for (const w of c.content) if (w.url) fuentes.push(f(w.url, w.title));
      }
    }
    const consultas = (r.content || [])
      .filter(c => c.type === 'server_tool_use' && c.name === 'web_search' && c.input && c.input.query)
      .map(c => String(c.input.query));
    return { disponible: true, texto, fuentes, consultas, error: '' };
  }
  if (motor === 'gemini') {
    const cand = (r.candidates && r.candidates[0]) || {};
    const texto = ((cand.content && cand.content.parts) || []).map(p => p.text || '').join('');
    // Gemini devuelve enlaces de redirección (vertexaisearch…); el dominio real viene en title.
    const meta = cand.groundingMetadata || {};
    const fuentes = (meta.groundingChunks || []).filter(c => c.web).map(c => {
      const titulo = c.web.title || '';
      return /\./.test(titulo) && !/\s/.test(titulo) ? f('https://' + titulo + '/', titulo) : f(c.web.uri, titulo);
    });
    return { disponible: true, texto, fuentes, consultas: (meta.webSearchQueries || []).map(String), error: '' };
  }
  if (motor === 'perplexity') {
    const msg = (r.choices && r.choices[0] && r.choices[0].message) || {};
    const fuentes = (r.search_results || []).map(s => f(s.url, s.title)).concat((r.citations || []).map(u => f(u, '')));
    return { disponible: true, texto: msg.content || '', fuentes, consultas: [], error: '' };
  }
  if (motor === 'ai_overview') {
    const aio = r.ai_overview;
    if (!aio || aio.error || !(aio.text_blocks || []).length) return vacia;
    const partes = [];
    const recorrer = bloques => {
      for (const b of bloques || []) {
        const linea = [b.title, b.snippet].filter(Boolean).join(' ');
        if (linea) partes.push(linea);
        if (b.list) recorrer(b.list);
        if (b.text_blocks) recorrer(b.text_blocks);
      }
    };
    recorrer(aio.text_blocks);
    const fuentes = (aio.references || []).map(x => f(x.link || x.source, x.title)).filter(x => x.url);
    return { disponible: true, texto: partes.join('\n'), fuentes, consultas: [], error: '' };
  }
  return Object.assign(vacia, { error: 'Motor desconocido: ' + motor });
}

// Las cinco respuestas de un prompt, una por motor. `apis` trae lo que devolvió
// cada nodo HTTP para ese prompt: {chatgpt, claude, gemini, perplexity,
// google, ai_overview_pagina}.
function juntarRespuestas(prompt, apis) {
  const pagina = apis.ai_overview_pagina;
  // Si hubo segunda llamada, el AI Overview viene ahí; si no, en la búsqueda.
  const aio = pagina && pagina.ai_overview ? pagina : apis.google;
  const crudas = {
    chatgpt: apis.chatgpt, claude: apis.claude, gemini: apis.gemini,
    perplexity: apis.perplexity, ai_overview: aio
  };
  // Un motor apagado (por ejemplo SerpAPI) no viene en `apis`: no genera fila.
  return Object.keys(crudas).filter(motor => crudas[motor] !== undefined).map(motor => {
    const e = extraerRespuesta(motor, crudas[motor]);
    // fuentes: dominios únicos (para citado_bcp y la columna fuentes).
    // citas: cada URL citada una vez, con título y lugar en la respuesta.
    const fuentes = [];
    const citas = [];
    for (const x of e.fuentes) {
      const url = typeof x === 'string' ? x : x.url;
      const d = dominioDe(url);
      if (!d) continue;
      if (!fuentes.includes(d)) fuentes.push(d);
      const limpia = /^https?:\/\//i.test(url) ? url : 'https://' + url;
      if (!citas.some(c => c.url === limpia)) {
        citas.push({ url: limpia.slice(0, 500), title: String((x && x.title) || '').slice(0, 160), domain: d, position: citas.length + 1 });
      }
    }
    return {
      run_id: prompt.run_id, fecha: prompt.fecha, timestamp: prompt.timestamp,
      prompt_id: prompt.id, proyecto: prompt.proyecto, categoria: prompt.categoria, prompt: prompt.prompt,
      motor,
      // ok: respondió. sin_overview: Google no mostró AI Overview. error: falló la llamada.
      estado: e.error ? 'error' : e.disponible ? 'ok' : 'sin_overview',
      texto: e.texto,
      fuentes,
      citas,
      consultas: (e.consultas || []).slice(0, 10),
      error: e.error
    };
  });
}

// «Banco Pichincha» → «Pichincha»: los nombres que devuelve el Analista pasan a
// los canónicos de config.js. Los bancos que no están en la lista quedan igual.
function marcasCanonicas(texto, config) {
  const clave = x => String(x || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  const marcas = [config.marca].concat(config.competidores || []);
  const salida = [];
  for (const nombre of String(texto || '').split(',').map(x => x.trim()).filter(Boolean)) {
    const m = marcas.find(b => [b.nombre].concat(b.alias || []).some(a => clave(a) === clave(nombre)));
    const final = m ? m.nombre : nombre;
    if (!salida.includes(final)) salida.push(final);
  }
  return salida.join(', ');
}

// Veces que el texto nombra alguno de los alias y dónde aparece el primero.
function apariciones(texto, alias) {
  const t = String(texto || '');
  const inicios = new Set();
  let primera = Infinity;
  for (const al of alias || []) {
    const re = new RegExp('(^|[^\\p{L}\\p{N}])' + String(al).replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '(?=$|[^\\p{L}\\p{N}])', 'giu');
    let m;
    // «Banco de Crédito» y «Banco de Crédito del Perú» empiezan en el mismo lugar: una sola vez.
    while ((m = re.exec(t))) { const i = m.index + m[1].length; inicios.add(i); primera = Math.min(primera, i); }
  }
  return { veces: inicios.size, primera };
}

function entero(v) {
  const n = Math.round(Number(v));
  return isFinite(n) && n > 0 ? n : 0;
}

// La fila de la hoja resultados: la respuesta más lo que dijo el Analista IA.
// Si el motor no respondió, no hay nada que analizar y la fila va sin mención.
function armarFila(r, analisis, config) {
  // Si el motor respondió pero el Analista falló, la fila no se puede contar:
  // va como error, no como «no menciona a BCP».
  if (r.estado === 'ok' && !analisis) {
    r = Object.assign({}, r, { estado: 'error', error: 'El Analista IA no devolvió resultado' });
  }
  const a = (r.estado === 'ok' && analisis) || {};
  let menciona = r.estado === 'ok' && (a.menciona_bcp === true || String(a.menciona_bcp).toLowerCase() === 'true');
  let posicion = Number(a.posicion_bcp);
  const sentimiento = Number(a.sentimiento);
  const dominios = (config.marca.dominios || []).map(d => d.toLowerCase());
  let detalle = r.estado === 'ok' ? detalleCanonico(a.detalle_marcas, config) : [];
  // Control: si el texto nombra a la marca y el Analista dijo que no (pasó
  // en 7 de 302 respuestas: «Interbank, BBVA, Scotiabank» contados y BCP no),
  // cuenta como mención, en el lugar en que aparece en el texto.
  const nombrada = r.estado === 'ok' && !menciona ? apariciones(r.texto, config.marca.alias) : null;
  if (nombrada && nombrada.veces) {
    menciona = true;
    const otras = detalle.filter(d => d.marca !== config.marca.nombre);
    const antes = otras.filter(d => {
      const m = [config.marca].concat(config.competidores || []).find(b => b.nombre === d.marca);
      const ap = apariciones(r.texto, m ? [m.nombre].concat(m.alias || []) : [d.marca]);
      return ap.veces && ap.primera < nombrada.primera;
    }).length;
    posicion = antes + 1;
    detalle = otras.slice(0, antes).concat([{ marca: config.marca.nombre, posicion, menciones: nombrada.veces, sentimiento: null, recomendada: false, atributos: [] }], otras.slice(antes))
      .map((d, i) => Object.assign(d, { posicion: i + 1 }));
    a.n_menciones_bcp = nombrada.veces;
    a.marcas_mencionadas = detalle.map(d => d.marca).join(', ');
  }
  const sov = sovPorMarca(detalle);
  return {
    run_id: r.run_id, fecha: r.fecha, timestamp: r.timestamp, prompt_id: r.prompt_id,
    proyecto: r.proyecto, categoria: r.categoria, prompt: r.prompt, motor: r.motor,
    estado: r.estado,
    menciona_bcp: menciona,
    posicion_bcp: menciona && posicion > 0 ? posicion : '',
    sentimiento: menciona && isFinite(sentimiento) ? Math.max(-1, Math.min(1, Math.round(sentimiento * 100) / 100)) : '',
    marcas_mencionadas: r.estado === 'ok' ? marcasCanonicas(a.marcas_mencionadas, config) : '',
    fuentes: r.fuentes.join(', '),
    citado_bcp: r.fuentes.some(d => esDominioPropio(d, dominios)),
    error: r.error || '',
    // Google Sheets no admite más de 50.000 caracteres por celda.
    respuesta: String(r.texto || '').slice(0, 20000),
    // Para el SOV por respuesta: veces que se nombra a BCP ÷ veces que se nombra a cualquier banco.
    n_menciones_bcp: menciona ? entero(a.n_menciones_bcp) : 0,
    n_menciones_bancos: r.estado === 'ok' ? entero(a.n_menciones_bancos) : 0,
    // Desglose por banco del Analista (nombres canónicos) y el Share of Voice de BCP.
    detalle_marcas: detalle.length ? JSON.stringify(detalle) : '',
    sov_bcp: r.estado !== 'ok' ? '' : menciona ? (sov[config.marca.nombre] || 0) : 0,
    // Cada URL citada (con título y lugar) y las consultas que hizo el motor al buscar.
    fuentes_detalle: (r.citas || []).length ? JSON.stringify(r.citas.slice(0, 40)) : '',
    consultas_busqueda: (r.consultas || []).length ? JSON.stringify(r.consultas) : ''
  };
}

// El detalle por banco del Analista, con nombres canónicos y un banco por fila
// (si la IA repite un banco con dos nombres, se suman sus menciones).
function detalleCanonico(texto, config) {
  const porMarca = new Map();
  for (const d of leerDetalle(texto)) {
    const marca = marcasCanonicas(d && d.marca, config);
    if (!marca) continue;
    const pos = Math.round(Number(d.posicion));
    const s = Number(d.sentimiento);
    const actual = porMarca.get(marca) || { marca, posicion: 0, menciones: 0, sentimiento: 0, recomendada: false, atributos: [] };
    if (pos > 0 && (!actual.posicion || pos < actual.posicion)) actual.posicion = pos;
    actual.menciones += Math.max(1, entero(d.menciones));
    if (isFinite(s)) actual.sentimiento = Math.max(-1, Math.min(1, Math.round(s * 100) / 100));
    // recomendada: la respuesta la propone como opción a elegir (probabilidad de compra).
    if (d.recomendada === true || String(d.recomendada).toLowerCase() === 'true') actual.recomendada = true;
    // atributos: solo los del vocabulario de config.js (perfil de marca).
    const vocab = (config.atributos || []).map(a => a.toLowerCase());
    for (const at of Array.isArray(d.atributos) ? d.atributos : []) {
      const k = String(at || '').toLowerCase().trim();
      if (vocab.includes(k) && !actual.atributos.includes(k)) actual.atributos.push(k);
    }
    porMarca.set(marca, actual);
  }
  // Posiciones 1..n en el orden que dio la IA, sin huecos.
  return [...porMarca.values()]
    .sort((x, y) => (x.posicion || 99) - (y.posicion || 99))
    .map((d, i) => Object.assign(d, { posicion: i + 1 }));
}

// El Analista devuelve un item por respuesta y en el mismo orden.
const r = $('Juntar respuestas').all()[$itemIndex].json;
return { json: armarFila(r, $json.output, CONFIG) };

const SHEET_ID = 'PEGA_AQUI_EL_ID_DE_TU_GOOGLE_SHEET';
// El Google Sheet, organizado como lo usa el equipo de BCP:
//   · una pestaña por proyecto con sus prompts (Marca, Ahorros, Cards…)
//   · una pestaña por día de medición con los resultados (2026-10-21, …)
//   · las que empiezan con «_» son de sistema (respaldos, notas) y se ignoran.
// Se lee y escribe con la API de Google Sheets (nodos HTTP con la credencial de
// Sheets); aquí solo se arman las peticiones y se interpretan las respuestas.
// Sin dependencias: build.mjs lo pega en los nodos Code que lo necesitan.

const SHEETS_API = 'https://sheets.googleapis.com/v4/spreadsheets/' + SHEET_ID;

// Encabezados de las pestañas de proyecto (los del Excel original de BCP, más
// id, activo y fecha para poder gestionarlos desde el front).
const COLUMNAS_PROMPTS = ['id', 'Categoría', 'Intención de Búsqueda', 'Prompt', 'Activo', 'Fecha de creación',
  'Tags', 'Etapa', 'Volumen', 'País'];
const COLUMNAS_RESULTADOS = ['run_id', 'fecha', 'timestamp', 'prompt_id', 'proyecto', 'categoria', 'prompt', 'motor', 'estado',
  'menciona_bcp', 'posicion_bcp', 'sentimiento', 'marcas_mencionadas', 'fuentes', 'citado_bcp', 'error', 'respuesta',
  'n_menciones_bcp', 'n_menciones_bancos', 'detalle_marcas', 'sov_bcp', 'fuentes_detalle', 'consultas_busqueda'];

function esPestanaFecha(titulo) { return /^\d{4}-\d{2}-\d{2}$/.test(String(titulo || '').trim()); }
function esPestanaSistema(titulo) { return String(titulo || '').trim().startsWith('_'); }
function esPestanaProyecto(titulo) { return !esPestanaFecha(titulo) && !esPestanaSistema(titulo) && String(titulo || '').trim() !== ''; }

function pestanas(meta) {
  return ((meta && meta.sheets) || []).map(s => s.properties).filter(Boolean)
    .map(p => ({ id: p.sheetId, titulo: p.title, indice: p.index }));
}

// Rango A1 de una pestaña, con el nombre entre comillas (acepta espacios y tildes).
function rango(titulo, celdas) {
  return "'" + String(titulo).replace(/'/g, "''") + "'!" + celdas;
}

// Cuerpo de values:batchGetByDataFilter para leer varias pestañas en una llamada.
// desde (AAAA-MM-DD): solo las pestañas de resultados desde esa fecha.
// Pestañas de sistema que lee el monitor: correcciones de categoría de dominio,
// estado de las recomendaciones y auditorías GEO.
const SISTEMA = ['_dominios', '_recomendaciones', '_auditorias'];

function cuerpoLectura(meta, { prompts = false, resultadosDesde = null, sistema = false } = {}) {
  const filtros = [];
  for (const p of pestanas(meta)) {
    if (prompts && esPestanaProyecto(p.titulo)) filtros.push({ a1Range: rango(p.titulo, 'A:J') });
    if (resultadosDesde && esPestanaFecha(p.titulo) && p.titulo >= resultadosDesde) filtros.push({ a1Range: rango(p.titulo, 'A:W') });
    if (sistema && SISTEMA.includes(p.titulo)) filtros.push({ a1Range: rango(p.titulo, 'A:H') });
  }
  // La API no acepta una lista vacía: sin nada que leer, se pide A1 de la primera pestaña.
  const primera = pestanas(meta)[0];
  if (!filtros.length && primera) filtros.push({ a1Range: rango(primera.titulo, 'A1:A1') });
  return { dataFilters: filtros, majorDimension: 'ROWS', valueRenderOption: 'UNFORMATTED_VALUE' };
}

function tituloDeRango(r) {
  const m = String(r || '').match(/^'((?:[^']|'')*)'!/) || String(r || '').match(/^([^!]+)!/);
  return m ? m[1].replace(/''/g, "'") : '';
}

function claveColumna(c) {
  const k = String(c || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();
  if (k === 'id') return 'id';
  if (k.startsWith('categ')) return 'categoria';
  if (k.startsWith('intenc')) return 'intencion';
  if (k.startsWith('prompt')) return 'prompt';
  if (k.startsWith('activo')) return 'activo';
  if (k.startsWith('fecha')) return 'fecha_creacion';
  if (k === 'tags' || k === 'tag') return 'tags';
  if (k.startsWith('etapa') || k.startsWith('funnel')) return 'etapa';
  if (k.startsWith('volumen')) return 'volumen';
  if (k === 'pais' || k === 'country') return 'pais';
  return '';
}

// Respuesta de batchGetByDataFilter → {prompts, resultados, sistema}.
// Cada prompt lleva su pestaña (= proyecto) y su número de fila.
function leerHojas(respuesta) {
  const prompts = [];
  const resultados = [];
  const sistema = {};
  for (const vr of (respuesta && respuesta.valueRanges) || []) {
    const v = vr.valueRange || vr;
    const titulo = tituloDeRango(v.range);
    const filas = v.values || [];
    if (!filas.length) continue;
    if (SISTEMA.includes(titulo)) {
      const cab = filas[0].map(String);
      sistema[titulo] = [];
      filas.slice(1).forEach((f, i) => {
        if (!f || !f.some(x => x !== '' && x !== null)) return;
        const o = { _fila: i + 2 };
        cab.forEach((c, j) => { o[c] = f[j] === undefined ? '' : f[j]; });
        sistema[titulo].push(o);
      });
    } else if (esPestanaFecha(titulo)) {
      const cab = filas[0].map(String);
      filas.slice(1).forEach(f => {
        if (!f || !f.some(x => x !== '' && x !== null)) return;
        const o = {};
        cab.forEach((c, i) => { o[c] = f[i] === undefined ? '' : f[i]; });
        resultados.push(o);
      });
    } else if (esPestanaProyecto(titulo)) {
      const cab = filas[0].map(claveColumna);
      filas.slice(1).forEach((f, i) => {
        if (!f || !f.some(x => x !== '' && x !== null)) return;
        const o = { proyecto: titulo, _fila: i + 2 };
        cab.forEach((c, j) => { if (c) o[c] = f[j] === undefined ? '' : f[j]; });
        if (o.fecha_creacion !== undefined) o.fecha_creacion = fechaTexto(o.fecha_creacion);
        prompts.push(o);
      });
    }
  }
  return { prompts, resultados, sistema };
}

// Las fechas pueden volver como número de serie de Sheets (UNFORMATTED_VALUE).
function fechaTexto(v) {
  if (typeof v === 'number' && v > 20000 && v < 80000) {
    return new Date(Date.UTC(1899, 11, 30) + v * 864e5).toISOString().slice(0, 10);
  }
  return String(v || '');
}

function valoresPrompt(p) {
  return [p.id, p.categoria || '', p.intencion || '', p.prompt || '', p.activo === false ? 'FALSE' : 'TRUE', p.fecha_creacion || '',
    (p.tags || []).join(', '), p.etapa || '', p.volumen ? p.volumen : '', p.pais || 'PE'];
}

function valoresResultado(f) {
  return COLUMNAS_RESULTADOS.map(c => {
    const v = f[c];
    return v === undefined || v === null ? '' : typeof v === 'boolean' ? (v ? 'TRUE' : 'FALSE') : v;
  });
}

// ─── Peticiones a la API de Sheets ─────────────────────────────────────────
const pedidoSheets = (method, ruta, body) => ({ method, url: SHEETS_API + ruta, body });
// Crea la pestaña y escribe sus filas en UNA sola petición (addSheet + appendCells
// con un sheetId elegido aquí). Con dos peticiones separadas, n8n las lanza con
// 300 ms de diferencia sin esperar la primera y la escritura puede llegar antes
// que la pestaña («Unable to parse range»): pasó en la corrida del 21/10.
function crearPestana(titulo, indice, filas, meta) {
  const usados = pestanas(meta).map(t => Number(t.id) || 0);
  let id = (Math.max(0, ...usados) % 2000000000) + 1;
  while (usados.includes(id)) id++;
  const celda = v => ({ userEnteredValue: typeof v === 'number' ? { numberValue: v } : typeof v === 'boolean' ? { boolValue: v } : { stringValue: v === null || v === undefined ? '' : String(v) } });
  const requests = [{ addSheet: { properties: Object.assign({ sheetId: id, title: titulo }, indice === undefined ? {} : { index: indice }) } }];
  if (filas && filas.length) requests.push({ appendCells: { sheetId: id, rows: filas.map(f => ({ values: f.map(celda) })), fields: 'userEnteredValue' } });
  return pedidoSheets('POST', ':batchUpdate', { requests });
}
const escribir = (titulo, desde, valores) =>
  pedidoSheets('PUT', '/values/' + encodeURIComponent(rango(titulo, desde)) + '?valueInputOption=RAW', { values: valores });
const agregar = (titulo, valores) =>
  pedidoSheets('POST', '/values/' + encodeURIComponent(rango(titulo, 'A1')) + ':append?valueInputOption=RAW&insertDataOption=INSERT_ROWS', { values: valores });
const borrarFila = (idPestana, fila) =>
  pedidoSheets('POST', ':batchUpdate', { requests: [{ deleteDimension: { range: { sheetId: idPestana, dimension: 'ROWS', startIndex: fila - 1, endIndex: fila } } }] });

// Crear, editar, activar/desactivar, mover de proyecto o eliminar un prompt.
// guardado: lo que devuelve prepararGuardado (prompts.js).
// → {ok, status, respuesta, peticiones}
function planGuardarPrompt(guardado, prompts, meta) {
  if (!guardado.ok) return { ok: false, status: 400, respuesta: { ok: false, error: guardado.error }, peticiones: [] };
  const tabs = pestanas(meta);
  const tab = titulo => tabs.find(t => t.titulo === titulo);
  const fila = guardado.fila;
  const actual = prompts.find(p => String(p.id).trim() === fila.id);
  const proyectosAlFinal = tabs.filter(t => esPestanaProyecto(t.titulo)).length;
  // Agrega filas a la pestaña del proyecto; si no existe, la crea con encabezados y filas a la vez.
  const agregarEn = (titulo, valores, pet) => {
    pet.push(tab(titulo) ? agregar(titulo, valores) : crearPestana(titulo, proyectosAlFinal, [COLUMNAS_PROMPTS].concat(valores), meta));
  };

  if (guardado.accion === 'eliminar') {
    if (!actual) return { ok: false, status: 404, respuesta: { ok: false, error: 'No existe el prompt ' + fila.id }, peticiones: [] };
    return { ok: true, status: 200, respuesta: { ok: true, accion: 'eliminar', id: fila.id }, peticiones: [borrarFila(tab(actual.proyecto).id, actual._fila)] };
  }

  if (guardado.accion === 'editar') {
    if (!actual) return { ok: false, status: 404, respuesta: { ok: false, error: 'No existe el prompt ' + fila.id }, peticiones: [] };
    // Se combina antes de normalizar, para que lo derivado (etapa según intención) use lo nuevo.
    const nuevo = normalizarPrompt(Object.assign({}, actual, fila));
    const pet = [];
    if (nuevo.proyecto === actual.proyecto) {
      pet.push(escribir(actual.proyecto, 'A' + actual._fila + ':J' + actual._fila, [valoresPrompt(nuevo)]));
    } else {
      // Cambio de proyecto: se agrega en la pestaña nueva y se borra de la vieja.
      agregarEn(nuevo.proyecto, [valoresPrompt(nuevo)], pet);
      pet.push(borrarFila(tab(actual.proyecto).id, actual._fila));
    }
    return { ok: true, status: 200, respuesta: { ok: true, accion: 'editar', prompt: limpio(nuevo) }, peticiones: pet };
  }

  // Crear: un proyecto nuevo crea su pestaña.
  const nuevo = normalizarPrompt(fila);
  const pet = [];
  agregarEn(nuevo.proyecto, [valoresPrompt(nuevo)], pet);
  return { ok: true, status: 200, respuesta: { ok: true, accion: 'crear', prompt: limpio(nuevo) }, peticiones: pet };
}

function limpio(p) {
  const o = {};
  for (const k of Object.keys(p)) if (!k.startsWith('_')) o[k] = p[k];
  return o;
}

// Guardar las filas de una corrida en la pestaña del día (se crea si no está,
// justo después de las pestañas de proyecto, para que la más reciente quede primero).
function planGuardarResultados(filas, meta) {
  const porFecha = new Map();
  for (const f of filas) {
    if (!porFecha.has(f.fecha)) porFecha.set(f.fecha, []);
    porFecha.get(f.fecha).push(valoresResultado(f));
  }
  const tabs = pestanas(meta);
  const proyectos = tabs.filter(t => esPestanaProyecto(t.titulo)).length;
  const pet = [];
  for (const [fecha, valores] of porFecha) {
    if (tabs.some(t => t.titulo === fecha)) pet.push(agregar(fecha, valores));
    else {
      pet.push(crearPestana(fecha, proyectos, [COLUMNAS_RESULTADOS].concat(valores), meta));
    }
  }
  return pet;
}

// ─── Pestañas de sistema (_recomendaciones, _dominios, _auditorias) ─────────
const COLUMNAS_SISTEMA = {
  _recomendaciones: ['id', 'estado', 'responsable', 'fecha_objetivo', 'fecha_hecha', 'actualizado'],
  _dominios: ['dominio', 'categoria', 'actualizado'],
  _auditorias: ['id', 'tipo', 'url', 'fecha', 'resultado']
};

// Agrega o actualiza el registro cuya columna `clave` coincide. Crea la pestaña
// (al final del Sheet) si todavía no existe.
function planUpsertSistema(titulo, registro, clave, filas, meta) {
  const columnas = COLUMNAS_SISTEMA[titulo];
  const valores = columnas.map(c => registro[c] === undefined || registro[c] === null ? '' : registro[c]);
  const existe = pestanas(meta).some(t => t.titulo === titulo);
  if (!existe) return [crearPestana(titulo, undefined, [columnas, valores], meta)];
  const actual = (filas || []).find(f => String(f[clave]).trim() === String(registro[clave]).trim());
  if (!actual) return [agregar(titulo, [valores])];
  const fin = String.fromCharCode(64 + columnas.length);
  const combinado = columnas.map((c, i) => (registro[c] === undefined ? (actual[c] === undefined ? '' : actual[c]) : valores[i]));
  return [escribir(titulo, 'A' + actual._fila + ':' + fin + actual._fila, [combinado])];
}

const ESTADOS_RECOMENDACION = ['suggested', 'todo', 'in_progress', 'done', 'archived'];

// POST /geo-recs-save: {id, estado, responsable?, fecha_objetivo?}
function planGuardarRecomendacion(body, filas, meta, ahora) {
  body = body || {};
  const id = String(body.id || '').trim();
  if (!id) return { ok: false, status: 400, respuesta: { ok: false, error: 'Falta el id de la recomendación.' }, peticiones: [] };
  const estado = body.estado === undefined ? undefined : String(body.estado).trim();
  if (estado !== undefined && !ESTADOS_RECOMENDACION.includes(estado)) {
    return { ok: false, status: 400, respuesta: { ok: false, error: 'Estado no válido: ' + estado }, peticiones: [] };
  }
  const previo = (filas || []).find(f => String(f.id).trim() === id);
  const registro = { id, actualizado: ahora };
  if (estado !== undefined) registro.estado = estado;
  if (body.responsable !== undefined) registro.responsable = String(body.responsable || '').trim().slice(0, 80);
  if (body.fecha_objetivo !== undefined) registro.fecha_objetivo = String(body.fecha_objetivo || '').slice(0, 10);
  // Al pasar a «hecha» se guarda la fecha, para medir el impacto después.
  if (estado === 'done' && !(previo && previo.fecha_hecha)) registro.fecha_hecha = ahora.slice(0, 10);
  if (!previo && registro.estado === undefined) registro.estado = 'suggested';
  return { ok: true, status: 200, respuesta: { ok: true, recomendacion: registro }, peticiones: planUpsertSistema('_recomendaciones', registro, 'id', filas, meta) };
}

// POST /geo-domain-save: {dominio, categoria}
function planGuardarDominio(body, filas, meta, ahora, categorias) {
  body = body || {};
  const dominio = String(body.dominio || '').trim().toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0];
  const categoria = String(body.categoria || '').trim();
  if (!dominio) return { ok: false, status: 400, respuesta: { ok: false, error: 'Falta el dominio.' }, peticiones: [] };
  if (!categorias.includes(categoria)) return { ok: false, status: 400, respuesta: { ok: false, error: 'Categoría no válida: ' + categoria }, peticiones: [] };
  const registro = { dominio, categoria, actualizado: ahora };
  return { ok: true, status: 200, respuesta: { ok: true, dominio: registro }, peticiones: planUpsertSistema('_dominios', registro, 'dominio', filas, meta) };
}

const meta = $('Pestañas del Sheet').first().json;
return planGuardarResultados($input.all().map(i => i.json), meta).map(p => ({ json: p }));
